<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap.php';
$slug=trim((string)($_GET['slug']??'')); if($slug===''){http_response_code(404);exit('Store not found.');}
$stmt=db()->prepare("SELECT sp.*,u.id seller_id FROM seller_profiles sp JOIN users u ON u.id=sp.user_id WHERE u.role='seller' AND u.status='active' AND sp.status='active' AND (sp.store_slug=:slug_exact OR (sp.store_slug IS NULL AND LOWER(REPLACE(sp.business_name,' ','-'))=:slug_fallback)) LIMIT 1");
$stmt->execute(['slug_exact'=>$slug,'slug_fallback'=>$slug]); $store=$stmt->fetch(PDO::FETCH_ASSOC); if(!$store){http_response_code(404);exit('Store not found.');}
$stmt=db()->prepare("SELECT p.* FROM products p WHERE p.seller_id=:sid AND p.status='active' ORDER BY p.created_at DESC LIMIT 48");$stmt->execute(['sid'=>(int)$store['seller_id']]);$products=$stmt->fetchAll(PDO::FETCH_ASSOC);
$title=$store['business_name'].' | DogoFlow';$desc=$store['store_description']?:'Shop products from '.$store['business_name'].' on DogoFlow.';$logo=trim((string)($store['store_logo']??''));$banner=trim((string)($store['store_banner']??''));$img=$banner?:($logo?:url('/assets/images/df-logo.png'));if(strpos($img,'http')!==0)$img=url('/'.ltrim($img,'/'));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><meta name="description" content="<?=e($desc)?>"><link rel="canonical" href="<?=e(url('/store.php?slug='.urlencode($slug)))?>"><meta property="og:type" content="website"><meta property="og:title" content="<?=e($title)?>"><meta property="og:description" content="<?=e($desc)?>"><meta property="og:url" content="<?=e(url('/store.php?slug='.urlencode($slug)))?>"><meta property="og:image" content="<?=e($img)?>"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="<?=e($title)?>"><meta name="twitter:description" content="<?=e($desc)?>"><meta name="twitter:image" content="<?=e($img)?>"><link rel="stylesheet" href="<?=e(url('/assets/css/app.css'))?>"></head><body><main class="df-stores-page">
<section class="card df-store-hero"><?php if($banner!==''): ?><img class="df-store-banner" src="<?=e(url('/'.ltrim($banner,'/')))?>" alt="<?=e($store['business_name'])?> cover"><?php endif; ?><div class="df-store-hero-content"><?php if($logo!==''): ?><img src="<?=e(url('/'.ltrim($logo,'/')))?>" alt="<?=e($store['business_name'])?> logo"><?php endif; ?><div><h1><?=e($store['business_name'])?></h1><p><?=e($desc)?></p><p><?=e((string)($store['store_location']??''))?></p><?php if(!empty($store['business_phone'])): ?><p>Contact: <?=e($store['business_phone'])?></p><?php endif; ?></div></div></section>
<header class="page-head"><h2>Products from this store</h2><p><?=count($products)?> products</p></header><div class="grid grid-4"><?php foreach($products as $p): ?><a class="card df-product-card" href="<?=e(url('/product.php?slug='.urlencode((string)$p['slug'])))?>"><?php $pimg=trim((string)($p['image']??'')); if($pimg!==''): ?><img src="<?=e(url('/'.ltrim($pimg,'/')))?>" alt="<?=e($p['name'])?>" loading="lazy"><?php else: ?><img src="<?=e(url('/assets/images/product-placeholder.png'))?>" alt="" loading="lazy"><?php endif; ?><h3><?=e($p['name'])?></h3><strong>GH₵ <?=e(number_format((float)$p['price'],2))?></strong></a><?php endforeach; ?><?php if(!$products): ?><div class="card"><p>This store has no published products yet.</p></div><?php endif; ?></div></main><?php require __DIR__.'/includes/footer.php'; ?></body></html>
